import { useState, type ReactNode } from 'react';
import { Meter, Toggle, ToggleGroup, cn, type MeterThresholds } from '@gntik-ai/ui';
import { formatQuantity } from '../format';
import { sampleQuotas } from './fixtures';

export interface Quota {
  id: string;
  label: string;
  used: number;
  limit: number;
  /** End-of-cycle projection. When any quota has one, a Current/Projected toggle appears. */
  projected?: number;
  /** Unit after the numbers, e.g. "requests" or "GB". */
  unit?: string;
  /** Helper line under the bar. Over the limit, a default overage note is shown. */
  note?: ReactNode;
}

export type QuotaScope = 'current' | 'projected';

export interface QuotaMetersProps {
  quotas?: Quota[];
  /** Heading above the meters. */
  title?: string;
  /** Percent-of-limit thresholds for amber and red (default 80 / 100). */
  thresholds?: MeterThresholds;
  /** Formats used/limit numbers. Default: grouped, compact above a million. */
  formatValue?: (value: number) => string;
  defaultScope?: QuotaScope;
  onScopeChange?: (scope: QuotaScope) => void;
  /** Heading level of the title, to fit the page outline (default h3). */
  titleAs?: 'h2' | 'h3' | 'h4';
  className?: string;
}

/** Plan quotas as meters: green with headroom, amber near the cap, red over it. */
export function QuotaMeters({
  quotas = sampleQuotas,
  title = 'Plan usage',
  thresholds,
  formatValue = formatQuantity,
  defaultScope = 'current',
  onScopeChange,
  titleAs: TitleTag = 'h3',
  className,
}: QuotaMetersProps) {
  const [scope, setScope] = useState<QuotaScope>(defaultScope);
  const canProject = quotas.some((q) => q.projected != null);
  const showProjected = canProject && scope === 'projected';

  const changeScope = (value: string[]) => {
    const next = value[0];
    if (next !== 'current' && next !== 'projected') return;
    setScope(next);
    onScopeChange?.(next);
  };

  return (
    <section aria-label={title} className={cn('grid gap-5', className)}>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <TitleTag className="text-[13px] font-medium text-muted-foreground">{title}</TitleTag>
        {canProject && (
          <ToggleGroup size="sm" aria-label="Usage period" value={[scope]} onValueChange={changeScope}>
            <Toggle value="current">Current cycle</Toggle>
            <Toggle value="projected">Projected</Toggle>
          </ToggleGroup>
        )}
      </div>
      <div className="grid grid-cols-1 gap-x-8 gap-y-6 sm:grid-cols-2">
        {quotas.map((q) => {
          const value = showProjected ? (q.projected ?? q.used) : q.used;
          const unit = q.unit ? ` ${q.unit}` : '';
          const text = `${formatValue(value)} / ${formatValue(q.limit)}${unit}`;
          const over = value - q.limit;
          const note = q.note ?? (over > 0 ? `${formatValue(over)}${unit} over the plan limit` : undefined);
          return (
            <Meter
              key={q.id}
              label={q.label}
              value={value}
              max={q.limit}
              thresholds={thresholds}
              valueLabel={text}
              aria-valuetext={text}
              note={note}
            />
          );
        })}
      </div>
    </section>
  );
}

import type { Quota } from './QuotaMeters';

/** Sample plan quotas: usage so far this cycle and the end-of-cycle projection. */
export const sampleQuotas: Quota[] = [
  { id: 'requests', label: 'Requests', used: 412_800, limit: 500_000, projected: 521_000, unit: 'requests' },
  { id: 'tokens', label: 'Tokens', used: 78_400_000, limit: 120_000_000, projected: 99_100_000, unit: 'tokens' },
  { id: 'storage', label: 'Storage', used: 14.2, limit: 20, projected: 17.1, unit: 'GB' },
  { id: 'seats', label: 'Seats', used: 38, limit: 50, projected: 38, unit: 'seats' },
];

/** Shared formatting for the billing blocks (en-US, Intl). */

/** A calendar date: a `Date` or an ISO `YYYY-MM-DD` string (read as a local date, no UTC shift). */
export type DateInput = Date | string;

export function toDate(value: DateInput): Date {
  if (value instanceof Date) return value;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return new Date(value);
}

const dateFmt = new Intl.DateTimeFormat('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
const shortDateFmt = new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

/** "June 1, 2026". */
export function formatDate(value: DateInput): string {
  return dateFmt.format(toDate(value));
}

/** "Jun 1, 2026". */
export function formatShortDate(value: DateInput): string {
  return shortDateFmt.format(toDate(value));
}

/** Money with the currency symbol: "$1,620.00" (or no decimals with `whole`). */
export function formatMoney(amount: number, currency = 'USD', whole = false): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: whole ? 0 : 2,
    maximumFractionDigits: whole ? 0 : 2,
  }).format(amount);
}

/** Grouped number, compact above a million: "412,800", "78.4M". */
export function formatQuantity(value: number): string {
  if (Math.abs(value) >= 1_000_000) {
    return new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 }).format(value);
  }
  return new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 }).format(value);
}
